"/us/en/acute-care/c/empowered-to-care-safe-patient-handling-and-nurse-protection": {"template":"base","metadata":{"title":"EmpowerED to Care: Safe Patient Handling and Nurse Protection in the ED","pageTitle":null,"description":"Explore ED nurse safety risks, costs of unsafe environments, and best practices for safe patient handling, violence prevention, and protective technologies.","image":"/content/dam/stryker/acute-care/campaigns/empowered-to-care/EmpowerED-to-Care_webinar_hero_1440x816.jpg","imageAlt":"Nurse pushing patient in strecher","tags":["stryker:business-unit/acute-care"],"originallyPublished":"2026-04-24T13:27:01.000Z","lastPublished":"2026-04-30T19:08:54.000Z","contentID":"AC-ACCL-SYK-3022242_REV-0_en_us"},"anchors":[],"disclaimer":null,"forms":[{"formId":"2921","afterSubmitAction":"redirectToPage","message":null,"useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/acute-care/c/hands-free-communication-nursing-care-eguide": {"template":"base","metadata":{"title":"The closer you are to the patient, the more you need your hands","pageTitle":"The closer you are to the patient, the more you need your hands","description":"This eGuide explores how four hospitals strengthened communication and coordination with our enterprise workflow platform—now featuring the hands-free Sync Badge. ","image":"/content/dam/stryker/acute-care/products/sync-badge/images/sync-badge_sizzle_800x600.jpg","imageAlt":"nurse wearing Sync badge standing next to patient in hospital bed","tags":[],"originallyPublished":"2025-06-16T17:42:31.000Z","lastPublished":"2026-08-13T18:46:31.000Z","contentID":"AC-SBA-SYK-1818451_REV-0_en_us"},"anchors":[],"disclaimer":"<p>1. Pepito J, Babate F, Dator W. The nurses' touch: An irreplaceable component of caring. Nurs Open. 2023;10(9):5838-5842.</p>","forms":[{"formId":"1315","afterSubmitAction":"showMessage","message":"Thank you. Please check your inbox for the eGuide download link.","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/acute-care/c/leading-the-digital-shift-nurse-executives-driving-future-care": {"template":"base","metadata":{"title":"Leading the Digital Shift Nurse Executives Driving Future Care","pageTitle":null,"description":"Healthcare is experiencing a digital shift, and nurse executives are critical to its success. This webinar will feature a fireside chat with nursing leaders who are guiding organizations through change. ","image":"/content/dam/stryker/acute-care/campaigns/leading-the-digital-shift/Leading-the-digital-shift-webinarhero_1440x816.jpg","imageAlt":"Nurse wearing Sync Badge, looking at large monitor on wall","tags":["stryker:business-unit/acute-care","stryker:business-unit/smart-care"],"originallyPublished":"2026-04-25T13:44:38.000Z","lastPublished":"2026-04-25T13:45:54.000Z","contentID":"AC-ACCL-SYK-3022150_REV-0_en_us"},"anchors":[],"disclaimer":null,"forms":[{"formId":"2921","afterSubmitAction":"redirectToPage","message":null,"useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
"/us/en/acute-care/c/smart-communication-to-enhance-school-safety": {"template":"base","metadata":{"title":"Smart communication to enhance school safety","pageTitle":null,"description":"Discover how wearable, voice-activated technology is helping schools facilitate everyday communication and emergency response. With one device, staff can call, message, broadcast and activate a panic alert—without reaching for a phone.","image":"/content/dam/stryker/acute-care/vocera/workplace-communication-solutions/vocera-education-thumbnail_1200x680.jpg","imageAlt":"Teacher wearing Smartbadge interacting with class","tags":[],"originallyPublished":"2025-06-06T20:19:35.000Z","lastPublished":"2026-08-13T18:48:04.000Z","contentID":"AC-VSB-SYK-1766400_REV-0_en_us"},"anchors":[],"disclaimer":null,"forms":[{"formId":"1315","afterSubmitAction":"showMessage","message":"Thank you. Please check your inbox for the white paper download link.","useProduction":true}],"tabs":[],"cardLists":[],"missingAlt":[]},
