"/us/en/portfolios/medical-surgical-equipment/integration-and-connectivity/or-integration/rise": {"template":"base","metadata":{"title":"RISE","pageTitle":null,"description":"RISE is Stryker’s integrated surgical platform for ENT and neurosurgery - built to streamline your OR with advanced surgical visualization, control, and connectivity. See the difference. Fill out the form to experience the RISE!","image":"/content/dam/stryker/portfolios/medical-surgical/integration-and-connectivity/rise/images/RISE_thumbnail.jpg","imageAlt":"RISE","tags":["stryker:specialty/OR-integration","stryker:content-type","stryker:business-unit/Navigation-NSE","stryker:business-unit/ent","stryker:portfolio/medical-and-surgical-equipment","stryker:capability/integration-and-connectivity","stryker:content-type/system","stryker:business-unit/endoscopy","stryker:content-type/hcp_content"],"originallyPublished":"2025-07-31T20:02:04.000Z","lastPublished":"2026-09-02T22:01:06.000Z","contentID":"ENDO-GSNPS-SYK-2116500_REV-1"},"anchors":[{"id":"your-or-your-way","title":"Your OR. Your Way.","hidden":true,"type":"section-title","area":"par"},{"id":"connectivity","title":"Connectivity","hidden":true,"type":"section-title","area":"par"},{"id":"visualization","title":"Visualization","hidden":true,"type":"section-title","area":"par"},{"id":"related-products","title":"Related products","hidden":true,"type":"section-title","area":"par"},{"id":"contact-us","title":"Contact us","hidden":true,"type":"section-title","area":"par"}],"disclaimer":"<div><b>References</b></div>\r\n<div>&nbsp;</div>\r\n<ol>\r\n<li>As compared to previous Stryker offering</li>\r\n<li>ENDO-GSNPS-OTHD-1937000</li>\r\n<li>1000904469</li>\r\n<li>COMMS-COMSO-WHPR-1532602</li>\r\n</ol>\r\n<div>*AIM = Advanced Imaging Modality</div>","forms":[{"formId":"4047","afterSubmitAction":"showMessage","message":"Thank you! We have received your request. A Stryker representative will be in contact with you soon.","useProduction":true}],"tabs":[],"cardLists":[{"component":"customizable","title":null,"items":[{"path":"/us/en/portfolios/medical-surgical-equipment/advanced-digital-healthcare","resolved":true,"title":"Advanced Digital Healthcare","description":"From advanced devices and software that transform care settings into state-of-the-art environments, to advanced visualization that guides surgeons and robotics with insightful analytics, Stryker’s Advanced Digital Healthcare is driving improved clinical, operational and financial outcomes across the continuum of care.","image":"/content/dam/stryker/portfolios/medical-surgical/advanced-digital-healthcare/images/screenshot-ADH copy.jpg","alt":null},{"path":"/us/en/endoscopy/products/1788-platform","resolved":true,"title":"1788 Platform for Minimally Invasive Surgery","description":"The 1788 Platform - A sophisticated surgical visualization system for multiple specialties, featuring vibrant images and enhanced fluorescence imaging capabilities.","image":"/content/dam/stryker/endoscopy/products/1788-platform/images/thumbnail.jpg","alt":"thumbnail"},{"path":"/us/en/communications/systems/-isuite-experience/connected-or-operating-system","resolved":true,"title":"Connected OR operating system","description":"Our Connected OR platform optimizes the surgical environment by leveraging intelligence and automation with efficiency & safety in mind, while enhancing the experience for the patient and surgical team.","image":"/content/dam/stryker/communications/systems/conntected-or/images/HeroHero.png","alt":null},{"path":"/us/en/communications/systems/-isuite-experience","resolved":true,"title":"The iSuite Experience","description":"You are team-oriented. We are too. Together we share a common goal of providing exceptional patient care. This begins with the iSuite - your customized, efficient, seamlessly integrated operating room. To create your iSuite, our team will guide you through the entire process, one we’ve successfully completed thousands of times. This includes designing and planning your room, providing world-class ","image":"/content/dam/stryker/communications/systems/isuite-experience/2022-assets/images/thumbnail.png","alt":"Operating room, Stryker Operating Room, iSuite, Operating Theater, Integrated operating room"},{"path":"/us/en/ent/products/pello-microdebrider","resolved":true,"title":"Pello microdebrider","description":"Meet Pello — Stryker’s innovative ENT microdebrider with proprietary blades, designed for reduced clogging, efficient cutting and reliability in ENT procedures.<sup>1</sup>","image":"/content/dam/stryker/ent/products/pello-microdebrider/Pello landing page Hero.png","alt":"Pello landing page Hero"},{"path":"/us/en/ent/products/stryker-ent-navigation-system","resolved":true,"title":"Stryker ENT navigation system","description":"The Stryker ENT navigation system powered by Scopis software is a next-generation solution. Designed to enhance precision*, the system can make a big impact by adapting to a variety of preferences and tools while harnessing the power of planning and augmented reality leading to enhanced visibility for enhanced surgical experiences. During surgery, the unique Scopis augmented reality technology ove","image":"/content/dam/stryker/ent/products/tgs-navigation/Stryker unit with pro cart_4Kmonitor_Scopis.jpg","alt":"stryker ent navigation system"},{"path":"/us/en/nse/products/high-speed-drills","resolved":true,"title":"High Speed Drills","description":"The most comprehensive and customizable neurosurgical high speed drill platform just grew stronger. With mechanics, motors and attachments, Signature 2 Portfolio aims to provide the exact tool and touch you want with the speed, power and durability you need.","image":"/content/dam/stryker/navigation/products/core-2-console/images/signature-2-iBur-family-1500x892.jpg","alt":"High speed drills"},{"path":"/us/en/nse/products/sonopet-iq","resolved":true,"title":"Sonopet iQ","description":"The Sonopet iQ Ultrasonic Aspirator not only delivers the power and control you need to fragment, emulsify and aspirate soft tissue and bone, but is also equipped with on-demand customizable features and RFID-enabled intelligence to help optimize your performance.","image":"/content/dam/stryker/nav-nse/products/sonopet-iq/images/sonopet-iq-console-handpiece.jpg","alt":"Sonopet iQ Ultrasonic Aspirator"}]}],"missingAlt":[]},
